"""Systems Mastery S07: networking for engineers (deep version: flows, real traces, worked interview scenarios)."""
import sysviz as v

URL_FLOW = v.seq(
    ["Browser", "DNS resolver", "Web server"],
    [("a->b", 0, 1, "1. DNS: address of www.example.com?"),
     ("a->b", 1, 0, "an A record, cached for its TTL", "reply"),
     ("a->b", 0, 2, "2. TCP SYN"),
     ("a->b", 2, 0, "SYN-ACK", "reply"),
     ("a->b", 0, 2, "ACK"),
     ("note", 0, 2, "3. TLS handshake: keys agreed, certificate checked"),
     ("a->b", 0, 2, "4. GET /  (Host: www.example.com)"),
     ("a->b", 2, 0, "200 OK + HTML", "reply"),
     ("note", 0, 2, "5. parse HTML, fetch CSS, JS, images (steps 4 again)")],
    "What happens when you open a URL", "Five stages, each with its own failure signature")

TCP_FLOW = v.seq(
    ["Client", "Server"],
    [("note", 0, 1, "handshake: agree starting sequence numbers"),
     ("a->b", 0, 1, "SYN  seq=x"),
     ("a->b", 1, 0, "SYN-ACK  seq=y  ack=x+1", "reply"),
     ("a->b", 0, 1, "ACK  ack=y+1"),
     ("note", 0, 1, "connection ESTABLISHED (1 round trip spent)"),
     ("a->b", 0, 1, "PSH  GET / ...  (100 bytes)"),
     ("a->b", 1, 0, "ACK  ack=x+101", "reply"),
     ("a->b", 1, 0, "PSH  200 OK ...  (1,460 bytes)", "reply"),
     ("a->b", 0, 1, "ACK  (a lost ACK would trigger a resend)"),
     ("a->b", 1, 0, "FIN  (server is done sending)", "reply"),
     ("a->b", 0, 1, "FIN, then ACK"),
     ("note", 0, 1, "closer waits in TIME_WAIT, then forgets the connection")],
    "A TCP connection from start to finish", "Numbers on every segment are what make delivery reliable and ordered")

DNS_FLOW = v.seq(
    ["Browser", "Resolver", "Root", ".com", "Authoritative"],
    [("a->b", 0, 1, "www.example.com?"),
     ("a->b", 1, 2, "who has .com?"),
     ("a->b", 2, 1, "ask the .com servers", "reply"),
     ("a->b", 1, 3, "example.com?"),
     ("a->b", 3, 1, "ask its name servers", "reply"),
     ("a->b", 1, 4, "www.example.com?"),
     ("a->b", 4, 1, "A record, TTL 300", "reply"),
     ("a->b", 1, 0, "answer (cached for TTL)", "reply")],
    "A DNS lookup with an empty cache", "The resolver walks down the hierarchy; every answer is cached for its TTL")

TLS_FLOW = v.seq(
    ["Client", "Server"],
    [("a->b", 0, 1, "ClientHello: versions, ciphers, key share, server name (SNI)"),
     ("a->b", 1, 0, "ServerHello: chosen cipher, key share", "reply"),
     ("note", 0, 1, "both sides now compute the same session keys"),
     ("a->b", 1, 0, "(encrypted) certificate chain + signature", "reply"),
     ("a->b", 1, 0, "(encrypted) Finished", "reply"),
     ("a->b", 0, 1, "(encrypted) Finished"),
     ("a->b", 0, 1, "(encrypted) HTTP request"),
     ("a->b", 1, 0, "(encrypted) HTTP response", "reply")],
    "A TLS 1.3 handshake", "One round trip before the first encrypted request can be sent")

WS_FLOW = v.seq(
    ["Browser", "Server"],
    [("a->b", 0, 1, "GET /chat  Upgrade: websocket  Sec-WebSocket-Key: ..."),
     ("a->b", 1, 0, "101 Switching Protocols  Sec-WebSocket-Accept: ...", "reply"),
     ("note", 0, 1, "same TCP connection stays open, now carrying frames"),
     ("a->b", 0, 1, "frame: \"hello\""),
     ("a->b", 1, 0, "frame: \"new message from Ben\" (pushed, not asked for)", "reply"),
     ("a->b", 1, 0, "frame: \"Ben is typing\"", "reply")],
    "A WebSocket conversation", "An HTTP request upgrades the connection into a two-way channel")

PROXY_FLOW = v.seq(
    ["Client", "Reverse proxy", "App server"],
    [("a->b", 0, 1, "HTTPS request (TLS ends here)"),
     ("note", 0, 1, "proxy: pick a healthy server, add X-Forwarded-For"),
     ("a->b", 1, 2, "plain HTTP request + X-Forwarded-For: client IP"),
     ("a->b", 2, 1, "response", "reply"),
     ("a->b", 1, 0, "response (maybe cached, maybe compressed)", "reply")],
    "A reverse proxy", "The client talks to the proxy; the proxy talks to the servers behind it")

LADDER = v.seq(
    ["You", "The path to the site"],
    [("a->b", 0, 1, "getent hosts name  (DNS)"),
     ("a->b", 0, 1, "nc -zv host port  (TCP)"),
     ("a->b", 0, 1, "openssl s_client -connect host:443  (TLS)"),
     ("a->b", 0, 1, "curl -sv https://host/  (HTTP and the app)"),
     ("note", 0, 1, "stop at the first step that fails: that is the layer to fix")],
    "The troubleshooting ladder", "Test the stages in the order a request meets them")

